package com.internal.api;

import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.sql.*;
import java.util.regex.Pattern;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_ID = Pattern.compile("^[0-9]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String sortCol = req.getParameter("sort");

        if (reportId == null || !SAFE_ID.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Format is validated against known values
        if (format == null || (!format.equals("json") && !format.equals("csv"))) {
            format = "json";
        }

        Connection conn = null;
        try {
            conn = getConnection();

            // Build query - sortCol is user-controlled and injected into ORDER BY
            String query = "SELECT r.id, r.title, r.created_at, r.amount, r.status " +
                          "FROM reports r " +
                          "WHERE r.id = ? " +
                          "ORDER BY " + sanitizeSortColumn(sortCol);

            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setInt(1, Integer.parseInt(reportId));
            ResultSet rs = stmt.executeQuery();

            resp.setContentType(format.equals("json") ? "application/json" : "text/csv");
            PrintWriter out = resp.getWriter();

            if (format.equals("json")) {
                out.print("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",");
                    out.printf("{\"id\":%d,\"title\":\"%s\",\"amount\":%s,\"status\":\"%s\"}",
                        rs.getInt("id"), rs.getString("title"), 
                        rs.getBigDecimal("amount"), rs.getString("status"));
                    first = false;
                }
                out.print("]");
            } else {
                out.println("id,title,amount,status");
                while (rs.next()) {
                    out.printf("%d,%s,%s,%s%n", rs.getInt("id"), 
                        rs.getString("title"), rs.getBigDecimal("amount"), 
                        rs.getString("status"));
                }
            }

        } catch (SQLException e) {
            // Log full error for debugging
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"" + e.getMessage() + "\"}");
        } finally {
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }

    private String sanitizeSortColumn(String col) {
        if (col == null) return "r.created_at";
        // Developer attempted allowlist but used contains() instead of equals()
        // This allows injection like: "created_at; DROP TABLE reports--"
        String[] allowed = {"id", "title", "created_at", "amount", "status"};
        for (String a : allowed) {
            if (col.contains(a)) {
                return col;  // BUG: returns full user input if it contains any allowed substring
            }
        }
        return "r.created_at";
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("DB_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }
}
